<p class="eyebrow">Portfolio</p><h1>Investments</h1><?php if(!$investments): ?><section class="empty-state"><h2>No investments yet</h2><p>Explore your Country Pack’s available opportunities.</p><a class="button" href="<?= e(route('companies.index')) ?>">Explore investments</a></section><?php else: ?><div class="card-grid"><?php foreach($investments as $i): ?><article class="card"><span class="badge"><?= e($i['status']) ?></span><h2><?= e($i['company_name_snapshot']) ?></h2><p><?= e($i['public_id']) ?></p><p><strong><?= money((int)$i['principal_amount_minor']) ?></strong> principal</p><p>Projected profit: <?= money((int)$i['projected_profit_amount_minor']) ?></p><a class="button button-secondary" href="<?= e(route('dashboard.investments.show',['investment'=>$i['public_id']])) ?>">View investment</a></article><?php endforeach; ?></div><?php endif; ?>
